/* Evidence, methods and user reproduction records. No external dependencies. */
(function(root){
 'use strict';
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const external=u=>/^https?:\/\//.test(u||'')?E(u):'';
 const asset=p=>/^assets\/[a-zA-Z0-9/_\-.]+$/.test(p||'')?(root.ATLAS_DATA.assetData?.[p]||'./'+p):'';
 const text=v=>Array.isArray(v)?v.map(x=>typeof x==='string'?x:JSON.stringify(x)).join('；'):typeof v==='object'&&v?JSON.stringify(v):String(v??'未核实');
 function table(t,caption){if(!t?.columns?.length||!Array.isArray(t.rows))return '';
  return `<div class="evidence-table-wrap" tabindex="0" role="region" aria-label="${E(t.caption||caption||'原文实验数据')}"><table class="evidence-table"><caption>${E(t.caption||caption||'原文关键数据')}</caption><thead><tr>${t.columns.map(x=>`<th scope="col">${E(text(x))}</th>`).join('')}</tr></thead><tbody>${t.rows.map(row=>`<tr>${(Array.isArray(row)?row:Object.values(row)).map(x=>`<td>${E(text(x))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${t.note?`<p class="data-note">${E(t.note)}</p>`:''}${t.sourceUrl&&external(t.sourceUrl)?`<p class="data-note"><a href="${external(t.sourceUrl)}" target="_blank" rel="noopener noreferrer">核对原文图表 ↗</a>　${E(t.locator||'')}</p>`:''}`;
 }
 function method(p){const m=p.method;if(!m)return '<p class="muted">原文方法尚未核实。已保留实际检索到的来源与缺口，不用推测补齐。</p>';
  const defs=[['input','输入'],['output','输出'],['assumptions','适用前提'],['difference','与相关路线的区别']];
  return `${m.explanation?`<div class="method-explanation"><p>${E(text(m.explanation))}</p></div>`:''}<dl class="definition-grid">${defs.map(([k,l])=>`<div class="${['assumptions','difference'].includes(k)?'wide':''}"><dt>${l}</dt><dd>${E(text(m[k]))}</dd></div>`).join('')}</dl>${Array.isArray(m.flow)&&m.flow.length?`<div class="flow" aria-label="方法总体流程">${m.flow.map(s=>`<div>${E(text(s))}</div>`).join('')}</div>`:''}${m.modules?.length?`<div class="method-modules">${m.modules.map((s,i)=>`<section class="method-module"><h3><span>${String(i+1).padStart(2,'0')}</span>${E(s.name||s.title||'关键模块')}</h3><p class="module-purpose">${E(s.purpose||s.role||'')}</p><dl><div><dt>处理什么</dt><dd>${E(text(s.input||m.input))}</dd></div><div class="module-mechanism"><dt>具体怎么做</dt><dd>${E(text(s.mechanism||s.detail||s.description||'未核实'))}</dd></div><div><dt>产生什么</dt><dd>${E(text(s.output||'详见模块机制'))}</dd></div></dl>${s.sourceUrl?`<a class="source-anchor" href="${external(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">模块依据 ↗ ${E(s.locator||'')}</a>`:''}</section>`).join('')}</div>`:'<p class="small-print">已核实内容按上方流程展示；模块级细节未补齐的部分不作推断。</p>'}`;
 }
 function evidence(p){const es=p.evaluation||[];return `<p class="small-print">以下均标注证据来源与比较条件。原文表值、作者正文报告和从图估读值应分别理解；不同数据集、预算和模型不组成统一排行榜。</p>${es.length?es.map(v=>`<section class="evidence-card"><h3>${E(v.benchmark||'原文实验')}<span class="evidence-label">${E(v.attribution||'作者报告')}</span></h3><p class="experiment-setting"><b>比较条件：</b>${E(text(v.setting))}</p><p>${E(text(v.result))}</p>${v.table?table(v.table,v.benchmark):''}${Array.isArray(v.tables)?v.tables.map(t=>table(t,v.benchmark)).join(''):''}${Array.isArray(v.metrics)?table({columns:['指标','数值','条件 / 单位'],rows:v.metrics.map(m=>[m.name||m.metric,m.value,m.condition||m.unit||'见比较条件'])},'关键指标'):''}<p class="data-note">原文定位：${E(v.locator||v.table?.locator||'待逐表复核')}${v.sourceUrl&&external(v.sourceUrl)?` · <a href="${external(v.sourceUrl)}" target="_blank" rel="noopener noreferrer">原始来源 ↗</a>`:''}</p>${v.caveat?`<p class="notice">${E(v.caveat)}</p>`:''}</section>`).join(''):'<p class="muted">尚未取得足够原文证据填入量化结果；详情来源中保留检索状态和待核实项。</p>'}`;
 }
 function reproduction(p){const r=p.reproduction;if(!r||r.status==='未复现')return '<div class="reproduction-empty"><span class="reproduction-label">未复现</span><p>目前未提供该论文的本地运行记录、配置与实验日志。论文作者的结果保留在上方“实验与证据”，不视为本网站已复现。</p></div>';
  const setup={task:'任务',split:'数据划分',episode:'Episode',languageModel:'LA模型',visionModel:'VA模型',rgbDepthResolution:'RGB / Depth 分辨率',hfov:'水平视场角',cameraPosition:'相机位置',depthRange:'深度范围',controller:'低层控制器',environment:'运行环境',instruction:'原始指令'};
  return `<div class="reproduction-intro"><span class="reproduction-label">${E(r.status)}</span><p>${E(r.summary)}</p><p class="data-note">${E(r.attribution)} · 整理日期 ${E(r.date)} · 来源：${E(r.source?.label)}</p></div><h3 class="content-subheading">实际配置与测试范围</h3><dl class="definition-grid">${Object.entries(setup).map(([k,l])=>`<div class="${['environment','instruction','controller'].includes(k)?'wide':''}"><dt>${l}</dt><dd>${E(r.setup?.[k]||'未记录')}</dd></div>`).join('')}</dl><h3 class="content-subheading">执行流程与触发条件</h3><div class="method-modules">${(r.pipeline||[]).map((s,i)=>`<section class="method-module"><h3><span>${String(i+1).padStart(2,'0')}</span>${E(s.name)}</h3><p>${E(s.detail)}</p><small>原PDF ${E(s.locator)}</small></section>`).join('')}</div><h3 class="content-subheading">关键步骤日志</h3>${table({caption:'用户记录中的关键步骤；step是环境计数，不是LLM调用次数',columns:['Step','模块','观察 / 进度','动作 / 停止','原始bbox','PDF定位'],rows:(r.timeline||[]).map(s=>[s.step,s.actor,s.observation,s.action,s.bbox?JSON.stringify(s.bbox):'—',s.locator])})}<h3 class="content-subheading">记录了什么，缺少什么</h3>${table({columns:['项目','记录值','解释 / 边界'],rows:(r.metrics||[]).map(x=>[x.name,x.value,x.type]),caption:'此处属于用户实测记录，不是论文正式评测成绩'})}<h3 class="content-subheading">复现观察与待排查问题</h3>${(r.observations||[]).map(o=>`<section class="reproduction-issue"><span class="source-kind user">${E(o.kind)}</span><h4>${E(o.title)}</h4><p>${E(o.detail)}</p><p><b>下一步核对：</b>${E(o.next)}</p></section>`).join('')}<h3 class="content-subheading">原始可视化证据</h3><div class="reproduction-gallery">${(r.gallery||[]).map(x=>`<figure><img loading="lazy" src="${E(asset(x.path))}" alt="${E(x.caption)}"><figcaption>${E(x.caption)} <span>PDF ${E(x.locator)}</span></figcaption></figure>`).join('')}</div><h3 class="content-subheading">继续复现所需材料</h3><ul class="reproduction-missing">${(r.missing||[]).map(x=>`<li>${E(x)}</li>`).join('')}</ul><div class="reproduction-sources">${root.ATLAS_DATA.offlinePreview?'<p class="data-note">原始PDF与全文文字提取随完整项目包提供；本单文件预览已内嵌上方图像与提取记录。</p>':`<a class="resource-link" href="${E(asset(r.source?.url))}" target="_blank" rel="noopener">打开原始测试PDF ↗</a><a class="resource-link" href="${E(asset(r.source?.textUrl))}" download>下载全文文字提取</a>`}<p class="data-note">${E(r.source?.locator)}</p></div>`;
 }
 root.AtlasDetail={method,evidence,reproduction,table};
})(typeof window!=='undefined'?window:globalThis);
